{
  "title": "Đà Lạt quanh hồ, tối xuống phố",
  "summary": "Một ngày thong thả quanh hồ Xuân Hương và khu trung tâm, ăn ngon, cà phê ấm, tối xuống phố đi bộ cho trọn vị Đà Lạt.",
  "stops": [
    {
      "poi_id": "p131",
      "kind": "activity",
      "must_do_id": null,
      "note": "Khởi động nhẹ nhàng bên hồ, gió se se mà lòng thư thả, chẳng cần đi xa vẫn thấy Đà Lạt hiền.",
      "must_do_id": null
    },
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh căn nóng giòn ngay khu trung tâm, ăn xong còn sức tản bộ tiếp, ngon quá (so tasty).",
      "must_do_id": null
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa gần hồ, đi chậm ngắm sắc màu, hợp với ngày không muốn rong ruổi xa.",
      "must_do_id": null
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ghé quán cà phê ấm cúng, ngồi nghe phố chuyển mình, đúng kiểu tối Đà Lạt thong dong.",
      "must_do_id": null
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa tối ngồi lại cho đàng hoàng, nem nướng thơm lừng, no bụng rồi mới tính chuyện đi chơi đêm.",
      "must_do_id": null
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tối xuống khu phức hợp đi bộ, đèn sáng rực rỡ, người Đà Lạt về đêm vui mà vẫn hiền.",
      "must_do_id": null
    }
  ]
}
```

