      "must_do_id": null
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Trưa ngồi xuống ăn nem nướng cho đúng chất Đà Lạt, chỗ này vừa miệng lại gần hồ.",
      "must_do_id": null
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa gần đó đi bộ tới được, ngắm hoa thong thả đúng kiểu chiều không vội.",
      "must_do_id": null
    },
    {
      "poi_id": "p330",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi lại quán cà phê mái ấm, ăn nhẹ rồi nhâm nhi cho hết một ngày gần gũi.",
      "must_do_id": null
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sau bữa tối ghé khu Marché cho có chút nhộn nhịp về đêm, vẫn trong trung tâm khỏi lo đi xa.",
      "must_do_id": null
    }
  ]
}
